        /// <summary>
        /// The splash runs on a separate UI thread, with its own Dispatcher, so the logo animation and the bar stay smooth while
        /// start-up does heavy work on the main window thread (building the pages, the first reads).
        /// The splash has its own resources (fixed colours in SplashWindow.xaml), and the progress events reach it through
        /// Dispatcher.Invoke. If the thread does not start → it runs on the main thread.
        /// </summary>
        private void ShowSplashOnOwnThread()
        {
            // usually already shown from App.OnStartup; here it is only taken over (or shown now, if it did not start then)
            if (SplashHost.ShowOnOwnThread()) { _splash = SplashHost.Current; return; }
            // fallback: the splash on the main thread
            _splash = new SMDWin.Views.SplashWindow();
            _splash.Show();
        }
