        private static void RefreshStatusBrushes()
        {
            var res = System.Windows.Application.Current?.Resources;
            if (res == null) return;
            static SolidColorBrush Frozen(System.Windows.Media.Color c) { var b = new SolidColorBrush(c); b.Freeze(); return b; }
            if (res["StatusCritBrush"] is SolidColorBrush crit) _brRed    = Frozen(crit.Color);
            if (res["StatusWarnBrush"] is SolidColorBrush warn) _brOrange = Frozen(warn.Color);
            if (res["StatusOkBrush"]   is SolidColorBrush ok)   _brGreen  = Frozen(ok.Color);
        }
        private static readonly SolidColorBrush _brGray   = MakeFrozenBrush(148, 163, 184);
        private static readonly SolidColorBrush _brCoolBlue = MakeFrozenBrush(56, 138, 221);
        private static SolidColorBrush MakeFrozenBrush(byte r, byte g, byte b)
        {
            var br = new SolidColorBrush(WpfColor.FromRgb(r, g, b));
            br.Freeze();
            return br;
        }

