        // The stress test intervals, in sample indices (_chartIdx) — drawn on the Temp & Stress charts as a coloured area with a
        // label. End = -1 while the test runs.
        private sealed class StressInterval { public string Kind = ""; public long Start; public long End = -1; }
        private readonly List<StressInterval> _stressIntervals = new();

        /// <summary>Opens/closes the interval of a stress type (CPU / GPU) by the current state.
        /// Called on every tick from UpdateStressTimers.</summary>
        private void TrackStressInterval(string kind, bool running)
        {
            var open = _stressIntervals.LastOrDefault(x => x.Kind == kind && x.End < 0);
            if (running && open == null)
                _stressIntervals.Add(new StressInterval { Kind = kind, Start = _chartIdx });
            else if (!running && open != null)
                open.End = _chartIdx;
            // Keep only the intervals that can still be visible (the buffer has ChartMaxPoints points)
            _stressIntervals.RemoveAll(x => x.End >= 0 && _chartIdx - x.End > ChartMaxPoints);
        }

        /// <summary>The scale for the network charts (KB/s): at least 1 MB/s, otherwise the maximum × 1.2 rounded to
        /// 1/2/5 × 10^n.</summary>
        private static float NiceNetScale(float maxKBs)
        {
            const float floorKBs = 1024f;
            float target = Math.Max(floorKBs, (float.IsFinite(maxKBs) ? maxKBs : 0f) * 1.2f);
            double mag = Math.Pow(10, Math.Floor(Math.Log10(target)));
            foreach (var m in new[] { 1.0, 2.0, 5.0, 10.0 })
                if (m * mag >= target) return (float)(m * mag);
            return target;
        }

        /// <summary>The hottest disk with a known temperature (NaN if none).</summary>
        private float CurrentDiskTempForChart()
        {
            float best = float.NaN;
            foreach (var t in _diskTempCache.Values)
                if (t > 0 && (float.IsNaN(best) || t > best)) best = (float)t;
            return best;
        }

        private float ComputeSystemPowerW(float? cpuW, float? gpuW, float? batteryLiveW, bool hasBattery)
        {
            if (batteryLiveW.HasValue && batteryLiveW.Value > 0)
                return batteryLiveW.Value;

            bool anyPowerKnown = (cpuW.HasValue && cpuW.Value > 0) || (gpuW.HasValue && gpuW.Value > 0);
            if (!anyPowerKnown) return float.NaN;

            float baseW = hasBattery ? 18f : 45f;
            return (cpuW ?? 0f) + (gpuW ?? 0f) + baseW;
        }
