        /// <summary>The number of "steps" (real seconds) _chartIdx must advance on this push, to catch up with the real delay
        /// since the last push. At least 1 (always advance at least one slot), capped at ChartCatchUpCapSlots.</summary>
        private int ComputeChartCatchUpSteps()
        {
            if (_lastChartPushUtc == DateTime.MinValue) { _lastChartPushUtc = DateTime.UtcNow; return 1; }
            double elapsedSec = (DateTime.UtcNow - _lastChartPushUtc).TotalSeconds;
            _lastChartPushUtc = DateTime.UtcNow;
            int steps = (int)Math.Round(elapsedSec);
            if (steps > 60) AppLogger.Debug($"ChartCatchUp: unusual gap of {steps}s between two pushes (UI thread possibly blocked under stress).");
            return Math.Max(1, Math.Min(steps, ChartCatchUpCapSlots));
        }
