        /// to redraw its live chart.</summary>
        internal event Action? PingDataUpdated;
        internal void StartAutoPingExternal(string host)
        {
            SettingsService.Current.PingBackgroundHost = host;
            SettingsService.Save();
            StartAutoPing(host);
        }
        internal void StopAutoPingExternal()
        {
            _pingCts?.Cancel();
            _pingRunning = false;
            StartDashboardBackgroundPing();
        }
        internal void SetPingBackgroundTrackingExternal(bool on)
        {
            SettingsService.Current.PingBackgroundTrackingEnabled = on;
            SettingsService.Save();
            if (on && !_pingRunning) StartAutoPingExternal(PingHostCurrent);
        }

        // Disk benchmark cancellation
