        // Report template

        private string _LS(string section, string key) => LanguageService.S(section, key);

        [System.Runtime.InteropServices.DllImport("user32.dll", CharSet = System.Runtime.InteropServices.CharSet.Auto)]
        private static extern IntPtr SendMessage(IntPtr hWnd, int Msg, IntPtr wParam, IntPtr lParam);

        private static bool _settingsPrepared;

        /// <summary>The settings and the language, only once. Called from App.OnStartup (so the splash already has the texts in
        /// the chosen language) and, as a fallback, from the constructor.</summary>
        internal static void PrepareSettingsAndLanguage()
        {
            if (_settingsPrepared) return;
            _settingsPrepared = true;
            SettingsService.Load();
            // Sync StartWithWindows from registry (actual state, not just saved setting)
            SettingsService.Current.StartWithWindows = IsStartWithWindowsEnabled();
            // Auto-detect OS language if user has never explicitly chosen one
            if (!SettingsService.Current.LanguageManuallySet)
            {
                string osCulture = System.Globalization.CultureInfo.CurrentUICulture.TwoLetterISOLanguageName.ToLower();
                var available = LanguageService.GetAvailablePacks().Select(p => p.Code).ToList();
                if (available.Contains(osCulture))
                    SettingsService.Current.Language = osCulture;
            }
            // Load language pack from Languages folder
            LanguageService.Load(SettingsService.Current.Language);
            SMDWin.Services.BootTiming.Mark("Settings and language loaded");
        }

        public MainWindow()
        {
            SMDWin.Services.BootTiming.Mark("MainWindow(): constructor start (after the services created as members)");

            PrepareSettingsAndLanguage();
            ButtonContrastGuard.Install();
            SMDWin.Services.BootTiming.Mark("MainWindow(): before InitializeComponent");
            InitializeComponent();
            // texts coloured with a fixed status brush keep the old theme's colour — tied to the theme after every change
            SMDWin.Services.ThemeManager.ThemeChanged += () => Dispatcher.BeginInvoke(new Action(RemapStatusColorsAfterTheme), System.Windows.Threading.DispatcherPriority.Background);
            // every modal window opened over the app (reports, driver search, PDF export…) dims the window behind it, like the dialogs
            ModalDim.Register();
            SetupResponsiveSoftwarePages();
            SMDWin.Services.BootTiming.Mark("MainWindow(): InitializeComponent (building the window and the pages)");
            CaptureLiteralSources();   // the XAML texts, before data or translations change them
            ApplyTempUnit();
            ApplyUiDensity();
            SMDWin.Services.BootTiming.Mark("MainWindow(): texts, units, density");

            // ApplyWpfUiTheme() is called only once, from ApplyCurrentTheme() (below).

            SMDWin.Services.NotificationCenter.Changed += UpdateNotifBadge;
            UpdateNotifBadge();
            UpdateHealthCheckBadge();
            var healthCheckStartupTimer = new DispatcherTimer { Interval = TimeSpan.FromSeconds(10) };
            healthCheckStartupTimer.Tick += async (_, _) =>
            {
                healthCheckStartupTimer.Stop();
                await RunBackgroundHealthCheckAsync();
            };
            healthCheckStartupTimer.Start();
            // The Drivers page: the slow WMI queries (~4-5 s) run in the background, after the app has settled, so the list is
            // already ready on first open (and the sidebar badge appears).
            var driversWarmTimer = new DispatcherTimer { Interval = TimeSpan.FromSeconds(30) };
            driversWarmTimer.Tick += async (_, _) =>
            {
                driversWarmTimer.Stop();
                try { await WarmDriversInBackgroundAsync(); }
                catch (Exception ex) { AppLogger.Debug($"WarmDrivers: {ex.Message}"); }
            };
            driversWarmTimer.Start();
            ThemeManager.ThemeChanged += RefreshVirtualizedGridsAfterThemeChange;
            ThemeManager.ThemeChanged += () =>
            {
                if (_allDisks != null && _allDisks.Count > 0 && DiskPanel != null)
                    PopulateDiskPanel(_allDisks);
            };
            ThemeManager.ThemeChanged += () => HighlightActiveNavIcon(_currentPanel);
            PreviewKeyDown += MainWindow_PreviewKeyDown;
            PreviewKeyDown += (_, e) =>
            {
                if (e.Key == System.Windows.Input.Key.LeftAlt || e.Key == System.Windows.Input.Key.RightAlt
                    || e.SystemKey == System.Windows.Input.Key.LeftAlt || e.SystemKey == System.Windows.Input.Key.RightAlt)
                    TechTooltip.SetAltState(true);
            };
            PreviewKeyUp += (_, e) =>
            {
                if (e.Key == System.Windows.Input.Key.LeftAlt || e.Key == System.Windows.Input.Key.RightAlt
                    || e.SystemKey == System.Windows.Input.Key.LeftAlt || e.SystemKey == System.Windows.Input.Key.RightAlt)
                    TechTooltip.SetAltState(false);
            };
            // If the window loses focus while Alt is pressed (e.g. Alt+Tab), PreviewKeyUp for Alt would never arrive — the state
            // would stay stuck "pressed". Deactivated guarantees the return to normal.
            Deactivated += (_, _) => TechTooltip.SetAltState(false);

            WindowState _prevState = WindowState.Normal;
            StateChanged += (_, _) =>
            {
                if (WindowState == WindowState.Minimized)
                {
                    _prevState = WindowState.Minimized;
                    _smoothRenderTimer?.Stop();
                    if (_dbRenderTimer != null)
                        _dbRenderTimer.Interval = TimeSpan.FromMilliseconds(2000);
                    ApplySensorCadence();
                }
                else
                {
                    if (_prevState == WindowState.Minimized)
                    {
                        _smoothRenderTimer?.Start();
                        if (_dbRenderTimer != null)
                            _dbRenderTimer.Interval = TimeSpan.FromMilliseconds(33);
                        ApplySensorCadence();
                    }
                    // Only activate/bring-to-front when genuinely restoring from minimized.
                    // If _prevState was Normal/Maximized, this is an owner-triggered state change
                    // (e.g. a secondary window closing) — do NOT steal focus in that case.
                    if (_prevState == WindowState.Minimized)
                    {
                        if (!IsVisible) Show();
                        Activate();
                        // Brief Topmost pulse forces window to front even when another app stole focus
                        Topmost = true;
                        Topmost = false;
                    }
                    _prevState = WindowState;
                }

                // Sync the glyph of the custom Maximize/Restore button for OTHER state transitions: restore from the taskbar,
                // Win+Up/Down, snap layouts, double click on the title, etc. (the native DWM buttons were replaced with custom buttons
                // — see UseAeroCaptionButtons="False" in XAML).
                SyncCaptionMaximizeGlyph();

                ApplyMaximizeBorderCompensation();
            };

            // Initial sync: the window starts Maximized, but StateChanged does not fire for the initial state (only on later
            // transitions).
            SyncCaptionMaximizeGlyph();

            ApplyCurrentTheme();
            SMDWin.Services.BootTiming.Mark("MainWindow(): theme applied");
            ApplyMaximizeBorderCompensation();
            // Adaptive dashboard card height — recalculate on every window resize
            SizeChanged += (_, _) => UpdateDashCardHeights();
            SizeChanged += RamStickDiagram_SizeChanged;
            StateChanged     += (_, _) => _uiVisibleCached = WindowState != System.Windows.WindowState.Minimized && IsVisible;
            IsVisibleChanged += (_, _) => _uiVisibleCached = WindowState != System.Windows.WindowState.Minimized && IsVisible;
            IsVisibleChanged += (_, _) => ApplySensorCadence();   // ascunsa in tray / readusa din tray

            void ApplyMaximizeBorderCompensation()
            {
                try
                {
                    // On Win11 with Mica + DwmExtendFrameIntoClientArea(-1), the content already reaches the real top edge when maximized.
                    // No padding is added on RootGrid.
                    if (FindName("RootGrid") is System.Windows.Controls.Grid rg)
                        rg.Margin = new Thickness(0);
                }
                catch (Exception ex) { AppLogger.Debug(ex.Message); }
            }

            SourceInitialized += (_, _) =>
            {
                // hidden from the screen until the first frame is drawn (MainWindow.StartupFade.cs) — no black flash
                CloakUntilReady();
                try
                {
                    var hwnd = new System.Windows.Interop.WindowInteropHelper(this).Handle;
                    var src = System.Windows.Interop.HwndSource.FromHwnd(hwnd);
                    src?.AddHook(MaximizeFixWndProc);
                }
                catch (Exception ex) { AppLogger.Debug(ex.Message); }

                try
                {
                    Microsoft.Win32.SystemEvents.PowerModeChanged += OnSystemPowerModeChanged;
                    Dispatcher.ShutdownStarted += (_, _) => Microsoft.Win32.SystemEvents.PowerModeChanged -= OnSystemPowerModeChanged;
                }
                catch (Exception ex) { AppLogger.Warning(ex, "PowerModeChanged subscribe"); }
            };

            Loaded += MainWindow_Loaded;
            Loaded += (_, _) => StartBatteryPowerSampler();   // the power history is collected even when the Battery page is not open
            Loaded += (_, _) => StartPlanPerSource();
            Loaded += (_, _) => _betaNoticeTask = ShowStartNoticesAsync();   // beta notice (first start only), then the safe-sensor notice (MainWindow.SensorSafeNotice.cs)         // laptop: the plan chosen for plugged in / on battery (MainWindow.PowerRedesign.cs)

            Loaded += (_, _) =>
            {
                try
                {
                    if (SystemParameters.WorkArea.Height < 800
                        && FindName("ExpDiskTools") is System.Windows.Controls.Expander expDt)
                        expDt.IsExpanded = false;
                }
                catch (Exception ex) { AppLogger.Debug(ex.Message); }
            };

            // Multiple passes needed: layout isn't stable until after ContentRendered
            // Pass 1: after Loaded
            Loaded += (_, _) => Dispatcher.BeginInvoke(
                System.Windows.Threading.DispatcherPriority.Loaded,
                new Action(() =>
                {
                    UpdateDashCardHeights();
                    // Capture the reference to the TextBlock in the Disk tooltip popup
                    _diskTooltipTb = FindName("TxtDashDiskTooltip") as System.Windows.Controls.TextBlock;
                }));
            // Pass 2: after background work (more stable)
            Loaded += (_, _) => Dispatcher.BeginInvoke(
                System.Windows.Threading.DispatcherPriority.Background,
                new Action(UpdateDashCardHeights));
            // Pass 3: after ContentRendered — most reliable, this is when ActualHeight is final
            ContentRendered += (_, _) =>
            {
                UpdateDashCardHeights();
                // Extra delayed pass for slow machines where layout takes longer
                Dispatcher.BeginInvoke(System.Windows.Threading.DispatcherPriority.ApplicationIdle,
                    new Action(UpdateDashCardHeights));
            };
            // Apply language after visual tree is ready (NavB traverses visual tree)
            Loaded += (_, _) => Dispatcher.InvokeAsync(
                () => ApplyLanguage(SettingsService.Current.Language),
                System.Windows.Threading.DispatcherPriority.Loaded);

            Loaded += (_, _) => Dispatcher.BeginInvoke(
                System.Windows.Threading.DispatcherPriority.Background,
                new Action(() =>
                {
                    if (_chartDefs.Count == 0) InitChartDefs();
                    RefreshAllSlots();
                }));
            // Defer chip/button highlight until after Loaded so TryFindResource has all resources
            Dispatcher.BeginInvoke(System.Windows.Threading.DispatcherPriority.Loaded,
                new Action(() =>
                {
                    LoadSettingsIntoUI();
                    ApplySidebarIconColors(SettingsService.Current.ColorfulIcons);
                }));
            // Re-apply after full render pass to overcome any inheritance override
            Dispatcher.BeginInvoke(System.Windows.Threading.DispatcherPriority.Render,
                new Action(() => ApplySidebarIconColors(SettingsService.Current.ColorfulIcons)));
            RefreshLangPackButtons();

            // ── Clock timer — tick every second ──────────────────────────────
            _clockTimer.Interval = TimeSpan.FromSeconds(1);
            _clockTimer.Tick += (_, _) =>
            {
                UpdateDashboardClock();
                try {
                    var uptime = SMDWin.Services.PowerOnClock.SinceOn;   // since power-on, not since the last full restart
                    string uptFmt = SMDWin.Services.DisplayFormat.Uptime(uptime);
                    if (FindName("TxtUptimeV") is System.Windows.Controls.TextBlock uptb) uptb.Text = uptFmt;
                    // the "System at a glance" card — Uptime + boot time
                    if (FindName("TxtGlanceUptime") is System.Windows.Controls.TextBlock gu) gu.Text = uptFmt;
                    // redrawn every 10 s: the power-on time arrives from the event log a moment after start-up
                    if (FindName("TxtGlanceBoot") is System.Windows.Controls.TextBlock gb && (gb.Text.Length == 0 || DateTime.Now.Second % 10 == 0))
                    {
                        var bootTime = DateTime.Now - uptime;
                        gb.Text = $"din {bootTime:dd-MM, HH:mm}";
                    }
                } catch (Exception ex) { AppLogger.Debug(ex.Message); }
                // refresh the top processes for the glance cards (every 3s, only on the Dashboard)
                if ((_currentPanel == "Dashboard" || _currentPanel == "")
                    && DateTime.Now.Second % 3 == 0)
                    _ = RefreshGlanceProcessesAsync();
                // Recheck heights every 5s in case window was resized
                if (DateTime.Now.Second % 5 == 0)
                    try { UpdateDashCardHeights(); } catch (Exception ex) { AppLogger.Debug(ex.Message); }
            };
            _clockTimer.Start();
            UpdateDashboardClock(); // initial paint before first tick
            for (int i = 0; i < ChartMaxPoints; i++) { _chartCpu[i] = float.NaN; _chartGpu[i] = float.NaN; _sparkGpuHistory[i] = float.NaN; _chartCpuSmooth[i] = float.NaN; _chartGpuSmooth[i] = float.NaN; _chartCpuFreq[i] = float.NaN; _chartCpuUsage[i] = float.NaN; _chartRamUsage[i] = float.NaN; _dashDiskRead[i] = float.NaN; _dashDiskWrite[i] = float.NaN; _dashNetDown[i] = float.NaN; _dashNetUp[i] = float.NaN; _chartCpuPower[i] = float.NaN; _chartGpuLoad[i] = float.NaN; _chartGpuFreq[i] = float.NaN; _chartGpuVram[i] = float.NaN; _chartGpuPower[i] = float.NaN; _chartCpuVCore[i] = float.NaN; _chartGpuMemFreq[i] = float.NaN; _chartDiskTemp[i] = float.NaN; }
            for (int i = 0; i < _pingHistory.Length; i++)  _pingHistory[i] = float.NaN;

            // Initialize the smooth chart buffers
            for (int i = 0; i < DashBufSize; i++)
            {
                _dbCpu[i] = _dbGpu[i] = _dbRam[i] = _dbDiskR[i] = _dbDiskW[i] =
                _dbNetDown[i] = _dbNetUp[i] = _dbPing[i] = _dbCpuTemp[i] = _dbGpuTemp[i] = float.NaN;
            }

            // Sync the chart window from the settings
            _chartTimeRangeSeconds = SettingsService.Current.ChartWindowSeconds;

            // Start the 30fps render timer for the dashboard charts
            _dbRenderTimer = new System.Windows.Threading.DispatcherTimer
            {
                // ~30 frames/s: without new data and without animation the tick exits immediately (see OnDashRenderTick)
                Interval = TimeSpan.FromMilliseconds(33)
            };
            _dbRenderTimer.Tick += OnDashRenderTick;
            _dbRenderTimer.Start();

            SMDWin.Services.BootTiming.Mark("MainWindow(): constructor almost done (before Loaded)");
            Loaded += async (_, _) =>
            {
                void LogBoot(string step) => SMDWin.Services.BootTiming.Mark(step);
                LogBoot("Loaded event fired");

                _ = _driverService.GetDriversAsync();

                // BOOT-SPLASH: hide the main window and show the splash until the real start-up sequence
                // (PawnIO -> LHM -> Sensors -> Dashboard) finishes. It is not a separate animation — StartupProgress is reported
                // directly from the real steps below.
                this.Visibility = Visibility.Hidden;
                ShowSplashOnOwnThread();
                SMDWin.Services.StartupProgress.Report(SMDWin.Services.StartupStep.PawnIO, LanguageService.S("Splash", "MsgPawnIO"));

                InitGpuStressTimer();
                _gpuStressTimer?.Stop();
                // A temporary Turbo change left over from a session that did not close normally: apply it back
                try
                {
                    if (SMDWin.Services.TurboRestore.HasPending && SMDWin.Services.TurboRestore.RestoreAndClear())
                        SMDWin.Services.ToolActivityLog.Add("Turbo Boost", "previous settings restored at start (last session did not close normally)", "warn");
                }
                catch (Exception ex) { AppLogger.Warning(ex, "Startup.turboRestore"); }
                // Processes left paused by a session that did not close normally: resume them
                try
                {
                    int resumed = SMDWin.Services.PausedProcesses.ResumeLeftovers();
                    if (resumed > 0)
                        SMDWin.Services.ToolActivityLog.Add("Processes", $"{resumed} paused process(es) resumed at start (last session did not close normally)", "warn");
                }
                catch (Exception ex) { AppLogger.Warning(ex, "Startup.pausedProcesses"); }
                InitTurboButtonState();
                try
                {
                    SetStressButtonIconState(BtnStressCpu, _cpuStress.Running);
                    SetStressButtonIconState(BtnStressGpu, _gpuStress.IsRunning);
                }
                catch (Exception logEx) { AppLogger.Debug(logEx.Message); }
                // Center window precisely on the screen that contains the cursor (works on multi-monitor laptops)
                var screen = System.Windows.Forms.Screen.FromHandle(
                    new System.Windows.Interop.WindowInteropHelper(this).Handle);
                // Apply rounded corners on Win11
                try { SMDWin.Services.ThemeManager.ApplyRoundedCorners(new System.Windows.Interop.WindowInteropHelper(this).Handle); } catch (Exception logEx) { AppLogger.Debug(logEx.Message); }
                var wa = screen.WorkingArea;
                double dpiX = 1.0, dpiY = 1.0;
                try {
                    var src = System.Windows.PresentationSource.FromVisual(this);
                    if (src?.CompositionTarget != null) {
                        dpiX = src.CompositionTarget.TransformToDevice.M11;
                        dpiY = src.CompositionTarget.TransformToDevice.M22;
                    }
                } catch (Exception ex) { AppLogger.Debug(ex.Message); }
                Left = wa.Left / dpiX + (wa.Width  / dpiX - ActualWidth)  / 2;
                Top  = wa.Top  / dpiY + (wa.Height / dpiY - ActualHeight) / 2;
                // Clamp so title bar is always reachable
                if (Top < wa.Top / dpiY)   Top  = wa.Top  / dpiY;
                if (Left < wa.Left / dpiX) Left = wa.Left / dpiX;

                InitNetToolMenu();

                // ── Build navigation lookup tables once ───────────────────────
                _navPanels = new Dictionary<string, UIElement>
                {
                    ["Dashboard"] = PanelDashboard, ["SysInfo"]    = CreateSysInfoPanel(), ["Stress"]     = PanelStress,
                    ["Benchmark"] = CreateBenchmarkPanel(),
                    ["Events"]    = PanelEvents,    ["Crash"]      = PanelCrash,
                    ["Drivers"]   = PanelDrivers,   ["Disk"]       = PanelDisk,
                    ["Ram"]       = PanelRamScroll,
                    ["Network"]   = PanelNetwork,   ["Apps"]       = PanelApps,
                    ["Services"]  = PanelServices,  ["Settings"]   = PanelSettings,
                    ["Processes"] = PanelProcesses, ["Startup"]    = PanelStartup,
                    ["Battery"]   = PanelBattery,
                    ["Tools"]     = PanelShutdown,
                    ["PowerShell"] = PanelPowerShell,
                };
                _navBtns = new Dictionary<string, Button>
                {
                    ["Dashboard"] = BtnDashboard,  ["SysInfo"]    = BtnSysInfo,  ["Stress"]     = BtnStress,
                    ["Benchmark"] = BtnBenchmark,
                    ["Events"]    = BtnEvents,     ["Crash"]      = BtnCrash,
                    ["Drivers"]   = BtnDrivers,    ["Disk"]       = BtnDisk,
                    ["Ram"]       = BtnRam,
                    ["Network"]   = BtnNetwork,    ["Apps"]       = BtnApps,
                    ["Services"]  = BtnServices,   ["Settings"]   = BtnSettings,
                    ["Processes"] = BtnProcesses,  ["Startup"]    = BtnStartup,
                    ["Battery"]   = BtnBattery,
                    ["Tools"]     = BtnShutdown,
                    ["PowerShell"] = BtnPowerShell,
                };
                _navStyleNormal = (Style)FindResource("NavButtonStyle");
                _navStyleActive = (Style)FindResource("NavButtonActiveStyle");
                _accentBrushCache = (Brush)FindResource("AccentBrush");

                // ── Set build date — use exe last-write time (actual build time) ─
                if (TxtBuildDate != null)
                {
                    DateTime buildTime;
                    try
                    {
                        // File last-write is set by the linker at build time — most reliable
                        var exePath = Environment.ProcessPath
                            ?? System.IO.Path.Combine(AppContext.BaseDirectory, AppDomain.CurrentDomain.FriendlyName);
                        buildTime = System.IO.File.GetLastWriteTime(exePath);
                        // Sanity check: if file time is suspiciously old (>1 year), fall back
                        if (buildTime < DateTime.Now.AddYears(-1))
                            buildTime = System.IO.File.GetLastWriteTime(
                                System.IO.Path.Combine(AppContext.BaseDirectory, AppDomain.CurrentDomain.FriendlyName));
                    }
                    catch
                    {
                        buildTime = DateTime.Now;
                    }
                    var __asmVer = System.Reflection.Assembly.GetExecutingAssembly().GetName().Version;
                    string __verStr = SMDWin.Services.AppVersionInfo.Short;
                    if (TxtBuildDate != null) TxtBuildDate.Text = $"{__verStr}  •  {SMDWin.Services.DateFormatHelper.FormatDateTime(buildTime)}";
                }

                // Show real admin status with prominent badge
                bool isAdmin = false;
                try
                {
                    using var identity  = System.Security.Principal.WindowsIdentity.GetCurrent();
                    var principal = new System.Security.Principal.WindowsPrincipal(identity);
                    isAdmin = principal.IsInRole(System.Security.Principal.WindowsBuiltInRole.Administrator);
                }
                catch (Exception ex) { AppLogger.Warning(ex, "MainWindow.unknown"); }
                if (TxtVersion != null)
                    TxtVersion.Text = "v4.0.0";
                // Update Admin badge — compact pill under logo
                if (AdminModeBadge != null && TxtAdminBadgeText != null)
                {
                    // Admin badge hidden — replaced by AdminLed next to logo
                    if (AdminModeBadge != null) AdminModeBadge.Visibility = Visibility.Collapsed;

                if (FindName("PortableModeBadge") is Border portBadge)
                    portBadge.Visibility = Visibility.Collapsed;
                    if (isAdmin)
                    {
                        bool isLightTheme = ThemeManager.IsLight(SettingsService.Current.ThemeName) ||
                            (SettingsService.Current.ThemeName == "Auto" && !ThemeManager.WindowsIsDark());
                        var textClr = isLightTheme
                            ? System.Windows.Media.Color.FromRgb(20, 83, 45)
                            : System.Windows.Media.Color.FromRgb(74, 180, 110);
                        var brdClr = isLightTheme
                            ? System.Windows.Media.Color.FromArgb(140, 20, 83, 45)
                            : System.Windows.Media.Color.FromArgb(120, 74, 180, 110);
                        var fgBrush = new System.Windows.Media.SolidColorBrush(textClr);

                        TxtAdminBadgeText.Text       = LanguageService.S("Common", "BadgeAdmin");
                        TxtAdminBadgeText.Foreground  = fgBrush;
                        if (AdminModeBadge != null) AdminModeBadge.Background = new System.Windows.Media.SolidColorBrush(
                            System.Windows.Media.Color.FromArgb(isLightTheme ? (byte)20 : (byte)30, textClr.R, textClr.G, textClr.B));
                        if (AdminModeBadge != null) AdminModeBadge.BorderBrush = new System.Windows.Media.SolidColorBrush(brdClr);
                        if (TxtAdminBadgeIcon != null) { TxtAdminBadgeIcon.Text = ""; TxtAdminBadgeIcon.Foreground = fgBrush; TxtAdminBadgeIcon.Visibility = Visibility.Visible; }
                    }
                    else
                    {
                        var amber = System.Windows.Media.Color.FromRgb(180, 120, 0);
                        var fgBrush = new System.Windows.Media.SolidColorBrush(amber);
                        TxtAdminBadgeText.Text       = LanguageService.S("Common", "BadgeUser");
                        TxtAdminBadgeText.Foreground  = fgBrush;
                        if (AdminModeBadge != null) AdminModeBadge.Background = new System.Windows.Media.SolidColorBrush(
                            System.Windows.Media.Color.FromArgb(25, 180, 120, 0));
                        if (AdminModeBadge != null) AdminModeBadge.BorderBrush = new System.Windows.Media.SolidColorBrush(
                            System.Windows.Media.Color.FromArgb(100, 180, 120, 0));
                        if (TxtAdminBadgeIcon != null) { TxtAdminBadgeIcon.Text = ""; TxtAdminBadgeIcon.Foreground = fgBrush; TxtAdminBadgeIcon.Visibility = Visibility.Visible; }
                    }
                }

                // ── Admin LED in sidebar (next to logo) ──
                if (AdminLed != null)
                {
                    var greenClr = (Application.Current.TryFindResource("StatusSuccessColor") as WpfColor?)
                                   ?? WpfColor.FromRgb(34, 197, 94);
                    var amberClr = (Application.Current.TryFindResource("StatusWarningColor") as WpfColor?)
                                   ?? WpfColor.FromRgb(245, 158, 11);
                    var ledColor = isAdmin ? greenClr : amberClr;
                    if (AdminLed != null) AdminLed.Fill = new System.Windows.Media.SolidColorBrush(ledColor);
                    if (AdminLed?.Effect is System.Windows.Media.Effects.DropShadowEffect dse)
                        dse.Color = ledColor;
                    if (TxtAdminLedTitle != null) TxtAdminLedTitle.Text = isAdmin ? "Administrator Mode" : "User Mode";
                    if (RunAdminLedDesc != null)
                        RunAdminLedDesc.Text = isAdmin
                            ? "Full access — all features available:"
                            : "Some features require Administrator privileges:";
                    var featureColor = isAdmin
                        ? (System.Windows.Media.Brush)FindResource("StatusOkBrush")
                        : (System.Windows.Media.Brush)FindResource("StatusErrorBrush");
                    if (RunFeature1 != null) { RunFeature1.Text = isAdmin ? "✓ CPU/GPU sensor temperatures" : "• CPU/GPU sensor temperatures"; RunFeature1.Foreground = featureColor; }
                    if (RunFeature2 != null) { RunFeature2.Text = isAdmin ? "✓ SMART disk health details"   : "• SMART disk health details";   RunFeature2.Foreground = featureColor; }
                    if (RunFeature3 != null) { RunFeature3.Text = isAdmin ? "✓ Hardware performance counters": "• Hardware performance counters"; RunFeature3.Foreground = featureColor; }
                    if (RunAdminLedAction != null) RunAdminLedAction.Text = isAdmin ? "" : "Click to restart as Administrator →";
                    if (BdrRestartAdmin != null)
                        BdrRestartAdmin.Visibility = isAdmin ? Visibility.Collapsed : Visibility.Visible;
                    UpdateSensorBackendLabel();
                }

                {
                    var greenBrush = new System.Windows.Media.SolidColorBrush(
                        (Application.Current.TryFindResource("StatusSuccessColor") as WpfColor?) ?? WpfColor.FromRgb(34, 197, 94));
                    var amberBrush = new System.Windows.Media.SolidColorBrush(
                        (Application.Current.TryFindResource("StatusWarningColor") as WpfColor?) ?? WpfColor.FromRgb(245, 158, 11));
                    var ledBrush = isAdmin ? greenBrush : amberBrush;
                    var ledClr = isAdmin
                        ? ((Application.Current.TryFindResource("StatusSuccessColor") as WpfColor?) ?? WpfColor.FromRgb(34, 197, 94))
                        : ((Application.Current.TryFindResource("StatusWarningColor") as WpfColor?) ?? WpfColor.FromRgb(245, 158, 11));

                    if (FindName("AdminLedBottom") is System.Windows.Shapes.Ellipse ledBottom)
                    {
                        ledBottom.Fill = ledBrush;
                        if (ledBottom.Effect is System.Windows.Media.Effects.DropShadowEffect dse2)
                            dse2.Color = ledClr;
                    }
                    if (FindName("TxtAdminLedLabel") is System.Windows.Controls.TextBlock ledLbl)
                    {
                        ledLbl.Text = isAdmin ? "ADMIN" : "USER";
                    }
                    if (FindName("TxtAdminStatusTitle") is System.Windows.Controls.TextBlock statusTitle)
                        statusTitle.Text = isAdmin ? "Administrator Mode" : "User Mode";

                    if (FindName("RunAdminStatusDesc") is System.Windows.Documents.Run descRun)
                        descRun.Text = isAdmin
                            ? _LS("Admin", "AdminDesc")
                            : "Some features require Administrator privileges.";
                    if (FindName("RunAdminStatusAction") is System.Windows.Documents.Run actionRun)
                        actionRun.Text = isAdmin ? "" : "Click to restart as Administrator →";
                }

                // ── Dashboard admin info banner — hidden, replaced by LED ──
                if (DashAdminBanner != null)
                    DashAdminBanner.Visibility = Visibility.Collapsed;

                // ── Always init tray icon (shows CPU temp even when window is open) ─
                InitTrayIcon();
                try { RebuildTraySensorIcons(); } catch (Exception ex) { AppLogger.Debug(ex.Message); }
                try { ApplySidebarAnimation(); } catch (Exception ex) { AppLogger.Debug(ex.Message); }
                try { ApplyDesignExperimentFont(); } catch (Exception ex) { AppLogger.Debug(ex.Message); }
                try { ApplySignatureMotifExperiment(); } catch (Exception ex) { AppLogger.Debug(ex.Message); }
                try { ApplyGrainTextureExperiment(); } catch (Exception ex) { AppLogger.Debug(ex.Message); }
                try { ApplyPowerMapExperiment(); BuildPowerPlanCards(); } catch (Exception ex) { AppLogger.Debug(ex.Message); }
                try { ApplyCornerRadiusExperiment(); } catch (Exception ex) { AppLogger.Debug(ex.Message); }
                try { ApplyShadowExperiment(); } catch (Exception ex) { AppLogger.Debug(ex.Message); }
                try { ApplySelectedButtonStyleExperiment(); } catch (Exception ex) { AppLogger.Debug(ex.Message); }
                try { ApplySidebarRailExperiment(); } catch (Exception ex) { AppLogger.Debug(ex.Message); }
                try { ApplyTaskBadgeStyle(); } catch (Exception ex) { AppLogger.Debug(ex.Message); }
                try { if (SettingsService.Current.WidgetEnabled) SetWidgetVisible(true); }
                catch (Exception ex) { AppLogger.Debug($"Widget auto-open: {ex.Message}"); }

                ThemeManager.MicaLayerOpacity = 1.0;
                ApplyCurrentTheme();

                // ── Start auto-theme watcher (polls Windows registry every 3s) ─
                if (SettingsService.Current.AutoTheme)
                    StartAutoThemeWatcher();

                // ── Set app icon from Assets/smdwin.png ─────────────────────
                _ = Dispatcher.InvokeAsync(() =>
                {
                    try
                    {
                        // The window icon stays the .ico from MainWindow.xaml (it has the simplified 16/20/24 px drawings for the
                        // title bar and the taskbar); the sidebar logo is the vector SmdLogo. Here only the activity state is applied.
                        UpdateLogoActivity(force: true);
                        SMDWin.Services.NetAlerts.Apply();   // network alerts switched on earlier: the ETW monitor starts in the background
                        StartCpuSelfWatch();
                    }
                    catch (Exception ex) { AppLogger.Warning(ex, "MainWindow.unknown"); }
                });

                // ── Parallel startup: WMI cache + TempReader + Dashboard ──────
                // Kick off WMI cache in background immediately
                var cacheTask = SMDWin.Services.WmiCache.Instance.RefreshAsync();
                // Start PerfmonService — collects counters every 1s in the background
                SMDWin.Services.PerfmonService.Instance.Start();
            try { InitPerfmonEventsOverlay(); } catch (Exception ex) { AppLogger.Debug(ex.Message); }
                var tempReaderTask = InitTempReaderThenStartTimer();

                // Load dashboard — runs concurrently with LHM/PawnIO init
                var dashboardTask = LoadDashboardAsync();

                // Wait for LHM/sensors first (they report PawnIO->Lhm->Sensors in order), then mark "Interface" — this way the splash
                // steps never jump ahead.
                await tempReaderTask;
                LogBoot("Sensors ready");
                SMDWin.Services.StartupProgress.Report(SMDWin.Services.StartupStep.Interfata, LanguageService.S("Splash", "MsgInterface"));
                await dashboardTask;
                LogBoot("Dashboard loaded");
                RefreshServiceToggleLabels();

                // the window appears immediately: charts without data show "Collecting data…" for a few seconds

                // BOOT-SPLASH: the dashboard and the sensors are ready — close the splash and show the real window.
                SMDWin.Services.StartupProgress.ReportReady();
                RevealWithFade();   // MainWindow.StartupFade.cs: drawn first, then shown with a short fade
                this.Visibility = Visibility.Visible;
                this.Activate();
                LogBoot("WINDOW VISIBLE");

                // after start-up has calmed down: the Windows data for System Info is read ahead of time (the first open took 3–4 s)
                _ = Task.Run(async () =>
                {
                    await Task.Delay(20_000);
                    SystemInfoView.PrewarmWindowsInfo();
                });

                // Preload the Process Monitor in the background at start-up
                // (PerformanceCounters need a first "prime" call before they return real values)
                _ = Task.Run(async () =>
                {
                    try { await _procMonitor.GetSnapshotAsync(5); } catch (Exception logEx) { AppLogger.Warning(logEx, "await _procMonitor.GetSnapshotAsync(5);"); }
                });

                _ = Task.Run(async () =>
                {
                    try
                    {
                        var pcR = new System.Diagnostics.PerformanceCounter("PhysicalDisk", "Disk Read Bytes/sec",  "_Total", true);
                        var pcW = new System.Diagnostics.PerformanceCounter("PhysicalDisk", "Disk Write Bytes/sec", "_Total", true);
                        pcR.NextValue(); pcW.NextValue(); // the first call — discard
                        await Task.Delay(1100);           // wait >1s
                        // Assign to the instance fields so the next GetSystemDiskIO reuses them
                        _pcDiskRead  = pcR;
                        _pcDiskWrite = pcW;
                    }
                    catch (Exception ex) { AppLogger.Warning(ex, "MainWindow.unknown"); }
                });

                // Load battery wear % via BatteryService (non-blocking, uses P/Invoke + WMI + powercfg fallbacks)
                _ = Task.Run(async () =>
                {
                    try
                    {
                        var batInfo = await _batterySvc.GetBatteryInfoAsync();
                        if (batInfo.Present && batInfo.WearPct.HasValue)
                            _batteryWearPct = batInfo.WearPct.Value;
                        else if (batInfo.Present)
                            _batteryWearPct = 0; // battery present but wear unknown → show 0 not —
                        // Update dashboard health badge now that we have real data
                        _ = Dispatcher.InvokeAsync(() =>
                        {
                            if (_summary != null) PopulateDashboardFromSummary(_summary);
                        });
                    }
                    catch (Exception ex) { AppLogger.Warning(ex, "MainWindow.unknown"); }
                });

                // Ensure cache is done before it might be needed by next nav
                await cacheTask;

                // ── Background ping for the Dashboard card — started automatically to 8.8.8.8 ──
                // Does not interfere with the Ping Monitor in the Network tab (the same _pingHistory)
                StartDashboardBackgroundPing();

                InitPingBackgroundTrackingOnStartup();

                // ── Attach rich tooltips to key action buttons ────────────────
                AttachRichTooltips();
                // ── Init breadcrumb for default page ─────────────────────────
                UpdateBreadcrumb("Dashboard");
            };

            Closed += (_, _) =>
            {
                try { _cpuStress.Stop(); } catch (Exception ex) { AppLogger.Debug(ex.Message); }
                try { _gpuStress.Stop(); } catch (Exception ex) { AppLogger.Debug(ex.Message); }
                try { _psuStress.Stop(); } catch (Exception ex) { AppLogger.Debug(ex.Message); }
                try { SettingsService.Save(); } catch (Exception ex) { AppLogger.Debug(ex.Message); }
                try { _notifyIcon?.Dispose(); } catch (Exception ex) { AppLogger.Debug(ex.Message); }
                try { DisposeTraySensorIcons(); } catch (Exception ex) { AppLogger.Debug(ex.Message); }
                try { StopAutoThemeWatcher(); } catch (Exception ex) { AppLogger.Debug(ex.Message); }

                // Signal the background tasks to stop (OnBgMonitorTick etc.)
                _appExiting = true;

                // Orderly shutdown. The native resources (LHM / driver) are closed FIRST and AWAITED (with a time limit) — a Task.Run
                // without waiting would be cut by Environment.Exit in App.OnExit within milliseconds, and the driver would not close.
                // The UI thread is blocked here on purpose: the window is already closed, and the steps below do not use the Dispatcher
                // (except DataProvider, which is limited to 2s).
                var shutdownSw = System.Diagnostics.Stopwatch.StartNew();
                var readerToClose = _tempReader;
                _dataProvider.DispatcherInvoke = null;
                var cleanup = System.Threading.Tasks.Task.Run(() =>
                {
                    bool lhmClosed = true;
                    try { lhmClosed = readerToClose?.CloseSafely(3000) ?? true; }
                    catch (Exception ex) { lhmClosed = false; AppLogger.Warning(ex, "Shutdown: TempReader.CloseSafely"); }
                    try { _speedTest.Dispose(); } catch (Exception ex) { AppLogger.Debug(ex.Message); }
                    try { _pingSvc?.Dispose(); } catch (Exception ex) { AppLogger.Debug(ex.Message); }
                    try { _procMonitor.Dispose(); } catch (Exception ex) { AppLogger.Debug(ex.Message); }
                    try { _netTrafficSvc.Dispose(); } catch (Exception ex) { AppLogger.Debug(ex.Message); }
                    try { _autoUpdate.Dispose(); } catch (Exception ex) { AppLogger.Debug(ex.Message); }
                    try { SMDWin.Services.PerfmonService.Instance.Dispose(); } catch (Exception ex) { AppLogger.Debug(ex.Message); }
                    try { _dataProvider.Dispose(); } catch (Exception ex) { AppLogger.Debug(ex.Message); }
                    try { SMDWin.Services.WmiCache.Instance.Dispose(); } catch (Exception ex) { AppLogger.Debug(ex.Message); }
                    return lhmClosed;
                });
                bool finished = false, lhmOk = false;
                try
                {
                    finished = cleanup.Wait(TimeSpan.FromSeconds(7));
                    lhmOk = finished && cleanup.Result;
                }
                catch (Exception ex) { AppLogger.Warning(ex, "Shutdown cleanup"); }
                AppLogger.Info("SHUTDOWN: cleanup {0} in {1}ms (sensor driver closed cleanly: {2})",
                    finished ? "completa" : "INTRERUPTA (timeout 7s)", shutdownSw.ElapsedMilliseconds, lhmOk);
            };
        }

        private const int WM_GETMINMAXINFO = 0x0024;

        [StructLayout(LayoutKind.Sequential)]
        private struct POINT { public int X; public int Y; }

        [StructLayout(LayoutKind.Sequential)]
        private struct MINMAXINFO
        {
            public POINT ptReserved;
            public POINT ptMaxSize;
            public POINT ptMaxPosition;
            public POINT ptMinTrackSize;
            public POINT ptMaxTrackSize;
        }

        [StructLayout(LayoutKind.Sequential)]
        private struct RECT { public int Left, Top, Right, Bottom; }

        [StructLayout(LayoutKind.Sequential)]
        private struct MONITORINFO
        {
            public int cbSize;
            public RECT rcMonitor;
            public RECT rcWork;
            public uint dwFlags;
        }

        [DllImport("user32.dll")]
        private static extern IntPtr MonitorFromWindow(IntPtr hwnd, uint dwFlags);

        [DllImport("user32.dll")]
        private static extern bool GetMonitorInfo(IntPtr hMonitor, ref MONITORINFO lpmi);

        private System.Windows.Threading.DispatcherTimer? _deviceChangeTimer;
        private string _deviceChangeDrives = "";
        private bool _deviceChangeForce;

        // the current "fingerprint" of storage: the letters of the ready fixed and removable drives + the physical disks (and
        // one without a letter: unformatted or with another file system) — it shows whether something changed in storage
        private static string ReadyDriveLetters()
        {
            string letters = "", disks = "";
            try
            {
                letters = string.Join(",", System.IO.DriveInfo.GetDrives()
                    .Where(d => d.DriveType is System.IO.DriveType.Fixed or System.IO.DriveType.Removable && d.IsReady)
                    .Select(d => d.Name));
            }
            catch (System.Exception __ignored) { SMDWin.Services.AppLogger.Swallowed(__ignored); }
            try
            {
                var ids = new List<string>();
                using var searcher = SMDWin.Services.WmiHelper.Searcher("SELECT DeviceID,Size FROM Win32_DiskDrive");
                using var found = searcher.Get();
                foreach (System.Management.ManagementBaseObject disk in found)
                    using (disk) ids.Add($"{disk["DeviceID"]}:{disk["Size"]}");
                ids.Sort(StringComparer.Ordinal);
                disks = string.Join(",", ids);
            }
            catch (System.Exception __ignored) { SMDWin.Services.AppLogger.Swallowed(__ignored); }
            return letters + " | " + disks;
        }

        /// <param name="volumeEvent">true = Windows announced a volume arrived / left; false = "something" changed in the devices
        /// (a message also sent for a modem, a camera, any USB device): the list is re-read only if the drive letters changed.</param>
        private void ScheduleStorageRefreshAfterDeviceChange(bool volumeEvent)
        {
            if (volumeEvent) _deviceChangeForce = true;
            if (_deviceChangeTimer == null)
            {
                _deviceChangeTimer = new System.Windows.Threading.DispatcherTimer { Interval = TimeSpan.FromMilliseconds(2000) };
                _deviceChangeTimer.Tick += async (_, _) =>
                {
                    _deviceChangeTimer!.Stop();
                    try
                    {
                        string now = await Task.Run(ReadyDriveLetters);
                        // the first time the previous list is not known: read it once
                        bool changed = _deviceChangeForce || now != _deviceChangeDrives;
                        _deviceChangeForce = false;
                        _deviceChangeDrives = now;
                        if (!changed || _allDisks.Count == 0) return;   // Storage not opened yet: it loads fresh anyway
                        AppLogger.Info($"Storage device connected/disconnected — refreshing the disk list (drives: {now})");
                        await LoadDisksInternalAsync(forceRefresh: true);
                    }
                    catch (Exception ex) { AppLogger.Debug($"deviceChange refresh: {ex.Message}"); }
                };
            }
            _deviceChangeTimer.Stop(); _deviceChangeTimer.Start(); // several events in a row = a single refresh
        }

        private IntPtr MaximizeFixWndProc(IntPtr hwnd, int msg, IntPtr wParam, IntPtr lParam, ref bool handled)
        {
            // USB / external disk inserted or removed: the disk list refreshes by itself (with a small delay, so Windows has time to
            // mount the volume and give it a letter)
            if (msg == 0x0219) // WM_DEVICECHANGE
            {
                long ev = wParam.ToInt64();
                if (ev == 0x8000 || ev == 0x8004) ScheduleStorageRefreshAfterDeviceChange(volumeEvent: true);   // DBT_DEVICEARRIVAL / DBT_DEVICEREMOVECOMPLETE
                else if (ev == 0x0007) ScheduleStorageRefreshAfterDeviceChange(volumeEvent: false);             // DBT_DEVNODES_CHANGED
            }
            if (msg == WM_GETMINMAXINFO)
            {
                try
                {
                    const uint MONITOR_DEFAULTTONEAREST = 0x00000002;
                    IntPtr monitor = MonitorFromWindow(hwnd, MONITOR_DEFAULTTONEAREST);
                    if (monitor != IntPtr.Zero)
                    {
                        var mi = new MONITORINFO { cbSize = Marshal.SizeOf(typeof(MONITORINFO)) };
                        if (GetMonitorInfo(monitor, ref mi))
                        {
                            var mmi = Marshal.PtrToStructure<MINMAXINFO>(lParam);
                            // The work area (without the taskbar), relative to the monitor.
                            mmi.ptMaxPosition.X = mi.rcWork.Left - mi.rcMonitor.Left;
                            mmi.ptMaxPosition.Y = mi.rcWork.Top  - mi.rcMonitor.Top;
                            mmi.ptMaxSize.X     = mi.rcWork.Right  - mi.rcWork.Left;
                            mmi.ptMaxSize.Y     = mi.rcWork.Bottom - mi.rcWork.Top;
                            // Min track size — the window cannot be made smaller than MinWidth/Height.
                            mmi.ptMinTrackSize.X = 900;
                            mmi.ptMinTrackSize.Y = 600;
                            Marshal.StructureToPtr(mmi, lParam, true);
                            handled = true;
                        }
                    }
                }
                catch (Exception ex) { AppLogger.Debug(ex.Message); }
            }
            return IntPtr.Zero;
        }

        protected override void OnClosing(System.ComponentModel.CancelEventArgs e)
        {
            bool closeToTrayEnabled = SettingsService.Current.CloseToTray;

            try
            {
                AppLogger.Info("OnClosing: _isClosingToTray={IsClosingToTray}, CloseToTray(settings)={CloseToTrayEnabled}, ChkMinimize.IsChecked={ChkChecked}",
                    _isClosingToTray, closeToTrayEnabled, ChkMinimize?.IsChecked);
            }
            catch (Exception ex) { AppLogger.Debug(ex.Message); }

            if (!_isClosingToTray && closeToTrayEnabled)
            {
                e.Cancel = true;
                try { InitTrayIcon(); AppLogger.Info("OnClosing: sent to tray (Hide + InitTrayIcon OK)"); }
                catch (Exception ex) { AppLogger.Warning(ex, "OnClosing: InitTrayIcon failed — hiding the window anyway, but the tray icon may be missing"); }
                Hide();
                // Do NOT reset _isClosingToTray here - it stays false.
                // It is set to true ONLY by the tray Exit
                return;
            }
            AppLogger.Info("OnClosing: proceeding with full close (not sent to tray)");
            _isClosingToTray = false; // reset for safety

            if (!closeToTrayEnabled)
            {
                try { _notifyIcon?.Dispose(); _notifyIcon = null; } catch (Exception ex) { AppLogger.Debug(ex.Message); }
            }

            // Close compact widget cleanly before teardown
            try { if (_compactWidget != null && _compactWidget.IsVisible) _compactWidget.Close(); } catch (Exception ex) { AppLogger.Debug(ex.Message); }

            if (_keepAwakeActive)
            {
                try { NativeMethods.SetThreadExecutionState(NativeMethods.ES_CONTINUOUS); } catch (Exception ex) { AppLogger.Debug(ex.Message); }
                _keepAwakeActive = false;
            }

            // Turbo changed "only while the program is open" returns to the previous settings; a permanent one stays
            try { if (SMDWin.Services.TurboRestore.RestoreAndClear()) SMDWin.Services.ToolActivityLog.Add("Turbo Boost", "previous settings restored when closing the app", "info"); }
            catch (Exception ex) { AppLogger.Warning(ex, "OnClosing.turbo"); }

            // Processes paused from SMD Win are never left frozen after it closes
            try
            {
                int resumed = SMDWin.Services.PausedProcesses.ResumeAll();
                if (resumed > 0) SMDWin.Services.ToolActivityLog.Add("Processes", $"{resumed} paused process(es) resumed when closing the app", "info");
            }
            catch (Exception ex) { AppLogger.Warning(ex, "OnClosing.pausedProcesses"); }

            // The scheduled shutdown stays armed in Windows after the app closes too: the user decides explicitly
            try
            {
                if (_shutdownTimer != null && _shutdownTimer.IsEnabled && _shutdownTargetTime > DateTime.Now)
                {
                    bool keep = AppDialog.Confirm(
                        $"A PC shutdown is scheduled for {_shutdownTargetTime:HH:mm}.\n\n" +
                        "Yes = keep it scheduled (the PC will still shut down after SMDWin is closed, open apps are closed without saving).\n" +
                        "No = cancel the shutdown.",
                        "Shutdown timer is active");
                    if (!keep)
                    {
                        System.Diagnostics.Process.Start(new System.Diagnostics.ProcessStartInfo("shutdown", "/a") { CreateNoWindow = true, UseShellExecute = false });
                        SMDWin.Services.ToolActivityLog.Add("Shutdown timer", "cancelled when closing the app", "info");
                    }
                    else SMDWin.Services.ToolActivityLog.Add("Shutdown timer", "left armed after closing the app", "warn");
                }
            }
            catch (Exception ex) { AppLogger.Warning(ex, "OnClosing.shutdownTimer"); }

            // Stop all timers immediately so they don't fire during teardown
            try { _procTimer.Stop(); } catch (Exception ex) { AppLogger.Debug(ex.Message); }
            try { _batTimer.Stop(); } catch (Exception ex) { AppLogger.Debug(ex.Message); }
            try { _trafficTimer.Stop(); } catch (Exception ex) { AppLogger.Debug(ex.Message); }
            try { _smoothRenderTimer.Stop(); } catch (Exception ex) { AppLogger.Debug(ex.Message); }
            try { _bgMonitorTimer.Stop(); } catch (Exception ex) { AppLogger.Debug(ex.Message); }
            try { _tempTimer.Stop(); } catch (Exception ex) { AppLogger.Debug(ex.Message); }
            try { _clockTimer.Stop(); } catch (Exception ex) { AppLogger.Debug(ex.Message); }
            try { _ramScanTimer?.Stop(); } catch (Exception ex) { AppLogger.Debug(ex.Message); }
            try { _shutdownTimer?.Stop(); } catch (Exception ex) { AppLogger.Debug(ex.Message); }
            try { StopNetPageTimer(); } catch (Exception ex) { AppLogger.Debug(ex.Message); }
            try { _dbRenderTimer?.Stop(); } catch (Exception ex) { AppLogger.Debug(ex.Message); }
            // Cancel all in-flight async operations
            try { _navCts?.Cancel(); } catch (Exception ex) { AppLogger.Debug(ex.Message); }
            try { _pingCts?.Cancel(); } catch (Exception ex) { AppLogger.Debug(ex.Message); }
            try { _diskBenchCts?.Cancel(); } catch (Exception ex) { AppLogger.Debug(ex.Message); }
            try { _portScanCts?.Cancel(); } catch (Exception ex) { AppLogger.Debug(ex.Message); }
            try { _dashPingCts?.Cancel(); } catch (Exception ex) { AppLogger.Debug(ex.Message); }
            try { _lanScanCts?.Cancel(); } catch (Exception ex) { AppLogger.Debug(ex.Message); }
            try { _ramTestCts?.Cancel(); } catch (Exception ex) { AppLogger.Debug(ex.Message); }
            try { _eventScanCts?.Cancel(); } catch (Exception ex) { AppLogger.Debug(ex.Message); }
            // Stop perf thread now so it doesn't access disposed counters
            try { StopPerfCounterThread(); } catch (Exception ex) { AppLogger.Debug(ex.Message); }
            // Dispose CancellationTokenSources to release any waiting threads
            try { _navCts?.Dispose(); } catch (Exception ex) { AppLogger.Debug(ex.Message); }
            try { _pingCts?.Dispose(); } catch (Exception ex) { AppLogger.Debug(ex.Message); }
            try { _diskBenchCts?.Dispose(); } catch (Exception ex) { AppLogger.Debug(ex.Message); }
            try { _portScanCts?.Dispose(); } catch (Exception ex) { AppLogger.Debug(ex.Message); }
            try { _dashPingCts?.Dispose(); } catch (Exception ex) { AppLogger.Debug(ex.Message); }
            try { _lanScanCts?.Dispose(); } catch (Exception ex) { AppLogger.Debug(ex.Message); }
            try { _ramTestCts?.Dispose(); } catch (Exception ex) { AppLogger.Debug(ex.Message); }

            base.OnClosing(e);
        }

        private void MainWindow_Loaded(object sender, RoutedEventArgs e)
        {
            // the signature of the app's own .exe (≈2.6 s) is checked once, in the background, so it does not delay the process list
            _ = Task.Run(() =>
            {
                try
                {
                    int budget = 1;
                    string? self = Environment.ProcessPath;
                    if (!string.IsNullOrEmpty(self)) SMDWin.Services.FileSignatureService.GetSignInfo(self, ref budget);
                }
                catch (Exception ex) { AppLogger.Debug("self signature warmup: " + ex.Message); }
            });
            // Adapt to smaller screens (below FHD) — clamp only if the window actually exceeds the screen
            _cachedWorkArea = SystemParameters.WorkArea;
            var workArea = _cachedWorkArea;
            // the default window is 1780×1120. On screens that cannot hold it (laptop, FHD) it shrinks to 94% of the work area and
            // is centred — it does not go off screen.
            double maxH  = workArea.Height * 0.94;
            double maxW  = workArea.Width  * 0.94;
            bool clamped = Height > maxH || Width > maxW;
            if (Height > maxH) Height = Math.Max(MinHeight, maxH);
            if (Width  > maxW) Width  = Math.Max(MinWidth,  maxW);
            if (clamped && WindowState == WindowState.Normal)
            {
                Left = workArea.Left + Math.Max(0, (workArea.Width  - Width)  / 2);
                Top  = workArea.Top  + Math.Max(0, (workArea.Height - Height) / 2);
            }
            // Centre if partly off screen
            if (Left + Width  > workArea.Right)  Left = Math.Max(0, workArea.Right  - Width);
            if (Top  + Height > workArea.Bottom) Top  = Math.Max(0, workArea.Bottom - Height);
        }

        internal void DashStorageDonut_Loaded(object sender, RoutedEventArgs e)
        {
            // Redraw the donut when the canvas becomes visible or is resized
            if (sender is not System.Windows.Controls.Canvas c || c.ActualWidth < 4) return;
            _ = Dispatcher.InvokeAsync(() =>
            {
                if (_lastDonutData?.Count > 0)
                    DrawStorageDonut(_lastDonutData);
            }, System.Windows.Threading.DispatcherPriority.Render);
        }

        private void RoundedClip_Apply(object sender, RoutedEventArgs e)
        {
            if (sender is not Border b || b.ActualWidth < 1 || b.ActualHeight < 1) return;
            double radius = (b.CornerRadius.TopLeft + b.CornerRadius.TopRight
                            + b.CornerRadius.BottomLeft + b.CornerRadius.BottomRight) / 4.0;
            b.Clip = new System.Windows.Media.RectangleGeometry(
                new Rect(0, 0, b.ActualWidth, b.ActualHeight), radius, radius);
        }

